// JAH demo program — Learning ladder
"use strict";
var __checks=[];
function check(l,g,w){__checks.push([l,g,w]);}
function rungs(){return ['curiosity','questions','basics','practice','feedback','plateau','breakthrough','teaching','mastery'];}
var r=rungs();
check("9 rungs", r.length, 9);
check("plateau before breakthrough", r.indexOf('plateau')<r.indexOf('breakthrough'), true);
check("teaching before mastery", r.indexOf('teaching')<r.indexOf('mastery'), true);
var __ok=true;
__checks.forEach(function(c){var ok=String(c[1])===String(c[2]);__ok=ok&&__ok;console.log((ok?"PASS":"FAIL")+" | "+c[0]+" => "+c[1]);});
console.log(__ok?"ALL CHECKS PASSED":"SOME CHECKS FAILED");
if(!__ok){throw new Error("demo self-check failed");}

